@startuml

class Student {
  + studentID : int
  + dateOfBirth : date
  + cityOfBirth : string
  + regionOfBirth : string
  + enrollmentYear : int
}

class Professor {
  + name : string
  + dateOfBirth : date
  + cityOfBirth : string
}

class Faculty {
  + name : string
  + type : string
}

class Course {
  + code : int
  + lectureHours : int
}

class Exam {
  + grade : string
}

Faculty "1" -- "1..*" Student : EnrolledIn
Faculty "1" -- "1..*" Course : BelongsTo
Professor "1..*" -- "0..*" Course : Teaches
Student "1" -- "0..*" Exam : Passes
Exam "0..*" -- "1" Course : For

@enduml

